<script setup lang="ts">import{ref,watch}from"vue";import{Download,FileText,Package,ShieldCheck}from"lucide-vue-next";import{api,apiError}from"../services/api";import{useAuthStore}from"../stores/auth";import{useTenantStore}from"../stores/tenant";const auth=useAuthStore(),tenant=useTenantStore(),tab=ref("sales"),rows=ref<any[]>([]),audit=ref<any[]>([]),inventory=ref<any>(null),error=ref(""),from=ref(""),to=ref(""),exporting=ref(false);const p=()=>({tenantId:auth.tenantId,warehouseId:tenant.activeWarehouseId||undefined,fromUtc:from.value||undefined,toUtc:to.value||undefined});async function load(){try{rows.value=(await api.get("/reports/sales-summary",{params:p()})).data;audit.value=(await api.get("/reports/audit-logs",{params:p()})).data;inventory.value=(await api.get("/reports/inventory-valuation",{params:p()})).data}catch(e){error.value=apiError(e)}}async function excel(){exporting.value=true;error.value="";try{const response=await api.get("/reports/sales/export-excel",{params:p(),responseType:"blob"});const url=URL.createObjectURL(response.data),link=document.createElement("a");link.href=url;link.download="ventas.xlsx";link.click();URL.revokeObjectURL(url)}catch(e){error.value=apiError(e)}finally{exporting.value=false}}watch(()=>auth.tenantId,load,{immediate:true});watch(()=>tenant.activeWarehouseId,load);</script><template><div class="page-heading"><div><div class="breadcrumb">Tu negocio / Reportes</div><h1>Reportes avanzados</h1><p>Ventas, inventario y trazabilidad.</p></div></div><div class="tabs"><button @click="tab='sales'">Ventas e IVA</button><button @click="tab='inventory'">Inventario</button><button @click="tab='audit'">Auditoría</button></div><section class="panel"><div class="inventory-toolbar"><label>Desde<input v-model="from" type="date"/></label><label>Hasta<input v-model="to" type="date"/></label><button class="secondary" @click="load">Aplicar</button><button v-if="tab==='sales'" class="primary" :disabled="exporting" @click="excel"><Download :size="16"/>{{exporting?'Generando…':'Exportar Excel (.xlsx)'}}</button></div><p v-if="error" class="error">{{error}}</p><div v-if="tab==='sales'" class="responsive-table"><table><thead><tr><th>Fecha</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Estado</th></tr></thead><tbody><tr v-for="r in rows"><td>{{new Date(r.date).toLocaleDateString('es-AR')}}</td><td>{{r.customer}}</td><td>${{r.total}}</td><td>{{r.paymentMethod}}</td><td>{{r.status}}</td></tr></tbody></table></div><div v-if="tab==='inventory'" class="account-summary"><article><Package/><div><p>Capital invertido</p><strong>${{inventory?.cost||0}}</strong></div></article><article><FileText/><div><p>Valor de venta</p><strong>${{inventory?.retail||0}}</strong></div></article></div><div v-if="tab==='audit'" class="statement-list"><article v-for="a in audit"><ShieldCheck/><div><strong>{{a.entityName}} · {{a.action}}</strong><small>{{new Date(a.timestampUtc).toLocaleString('es-AR')}}</small></div></article></div></section></template>
